-- FitMind AI: administração, planos e financeiro. Execute após supabase/schema.sql.
-- Preserva os registros da tabela subscriptions já existente.
create extension if not exists pgcrypto;
alter table public.profiles add column if not exists account_status text not null default 'active' check (account_status in ('active','suspended','blocked'));
create table if not exists public.user_roles (user_id uuid primary key references auth.users(id) on delete cascade, role text not null default 'user' check(role in ('admin','user')), created_at timestamptz not null default now());
create table if not exists public.plans (id uuid primary key default gen_random_uuid(), code text not null unique check(code in ('free','premium_monthly','premium_yearly')), name text not null, description text, billing_interval text not null check(billing_interval in ('none','month','year')), price_cents integer not null default 0 check(price_cents>=0), currency text not null default 'BRL', is_active boolean not null default true, is_configured boolean not null default true, features jsonb not null default '[]'::jsonb, updated_at timestamptz not null default now(), created_at timestamptz not null default now());
insert into public.plans(code,name,description,billing_interval,price_cents,is_configured,features) values ('free','Gratuito','Recursos essenciais para começar.','none',0,true,'["Treinos básicos","Acompanhamento inicial"]'),('premium_monthly','Premium mensal','Assinatura recorrente mensal.','month',0,false,'["Treinos personalizados","Histórico completo","Recursos premium"]'),('premium_yearly','Premium anual','Assinatura recorrente anual.','year',0,false,'["Treinos personalizados","Histórico completo","Recursos premium"]') on conflict(code) do nothing;
alter table public.subscriptions add column if not exists plan_id uuid references public.plans(id);
alter table public.subscriptions add column if not exists cancel_at_period_end boolean not null default false;
alter table public.subscriptions add column if not exists updated_at timestamptz not null default now();
update public.subscriptions s set plan_id=p.id from public.plans p where s.plan_id is null and p.code=case when s.plan='premium' then 'premium_monthly' else 'free' end;
create table if not exists public.payments (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, subscription_id uuid references public.subscriptions(id) on delete set null, plan_id uuid references public.plans(id) on delete set null, provider text not null default 'mercado_pago', provider_payment_id text unique, amount_cents integer not null check(amount_cents>=0), currency text not null default 'BRL', status text not null default 'pending' check(status in ('pending','approved','rejected','refunded','cancelled','charged_back')), description text, paid_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.payment_methods (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, provider text not null, provider_method_id text not null, brand text, last_four text check(last_four is null or last_four ~ '^[0-9]{4}$'), is_default boolean not null default false, created_at timestamptz not null default now(), unique(user_id,provider,provider_method_id));
create table if not exists public.invoices (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, payment_id uuid references public.payments(id) on delete set null, provider_invoice_id text, invoice_url text, status text not null default 'issued', issued_at timestamptz not null default now());
create table if not exists public.payment_events (id uuid primary key default gen_random_uuid(), provider text not null, provider_event_id text not null, event_type text not null, processed_at timestamptz, created_at timestamptz not null default now(), unique(provider,provider_event_id));
create table if not exists public.admin_logs (id uuid primary key default gen_random_uuid(), admin_user_id uuid references auth.users(id) on delete set null, target_user_id uuid references auth.users(id) on delete set null, action text not null, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.user_roles where user_id=auth.uid() and role='admin') $$;
alter table public.user_roles enable row level security; alter table public.plans enable row level security; alter table public.payments enable row level security; alter table public.payment_methods enable row level security; alter table public.invoices enable row level security; alter table public.payment_events enable row level security; alter table public.admin_logs enable row level security;
drop policy if exists "roles own read" on public.user_roles; create policy "roles own read" on public.user_roles for select to authenticated using(user_id=auth.uid() or public.is_admin());
drop policy if exists "plans readable" on public.plans; create policy "plans readable" on public.plans for select to authenticated using(is_active or public.is_admin());
drop policy if exists "plans admin manage" on public.plans; create policy "plans admin manage" on public.plans for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists "payments own read" on public.payments; create policy "payments own read" on public.payments for select to authenticated using(user_id=auth.uid() or public.is_admin());
drop policy if exists "payment methods own read" on public.payment_methods; create policy "payment methods own read" on public.payment_methods for select to authenticated using(user_id=auth.uid() or public.is_admin());
drop policy if exists "invoices own read" on public.invoices; create policy "invoices own read" on public.invoices for select to authenticated using(user_id=auth.uid() or public.is_admin());
drop policy if exists "payment events admin only" on public.payment_events; create policy "payment events admin only" on public.payment_events for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists "admin logs admin read" on public.admin_logs; create policy "admin logs admin read" on public.admin_logs for select to authenticated using(public.is_admin());
drop policy if exists "profiles admin read" on public.profiles; create policy "profiles admin read" on public.profiles for select to authenticated using(public.is_admin());
drop policy if exists "profiles admin update" on public.profiles; create policy "profiles admin update" on public.profiles for update to authenticated using(public.is_admin()) with check(public.is_admin());
create index if not exists payments_user_date_idx on public.payments(user_id,created_at desc); create index if not exists payments_status_idx on public.payments(status); create index if not exists admin_logs_date_idx on public.admin_logs(created_at desc);
-- Bootstrap seguro: depois de criar a conta proprietária no Auth, execute no SQL Editor confiável:
-- insert into public.user_roles(user_id,role) select id,'admin' from auth.users where email='SEU_EMAIL_ADMIN' on conflict(user_id) do update set role='admin';
-- Nunca crie uma tela pública para atribuir a função admin. Preços Premium ficam não configurados até serem definidos.
